      switch (nCallResult) {
        case 1:
          {
            nParticleOffset = -(ScreenSizeX / 4);
            __frame0.nScreenX += nParticleOffset;
            break;
          }
        case 2:
          {
            nParticleOffset = ScreenSizeX / 4;
            __frame0.nScreenX += nParticleOffset;
            break;
          }
      }

      __frame0.nScreenY += 0x10;
      nCoord = Particle::PARTICLE_GetX(pUnit);
      __frame0.nScreenX += nCoord;
      nParticleOffset = Particle::PARTICLE_GetY(pUnit);
